/* Fast dominant eigenpair for small real square matrices (n <= 16).
 *
 * Public interface: _fasteig.dominant(A) -> (eigenvalue, vector_bytes, is_complex)
 * or None when the internal solver cannot certify the result (caller falls
 * back to numpy).
 *
 * Input is read through the PEP 3118 buffer protocol, output is returned as a
 * bytearray, so this module does not depend on the numpy C ABI.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <complex.h>
#include <math.h>
#include <string.h>

#define MAXN 16

/* LAPACK (netlib / reference, 32-bit integers) */
extern void dgeev_(char *jobvl, char *jobvr, int *n, double *a, int *lda,
                   double *wr, double *wi, double *vl, int *ldvl, double *vr,
                   int *ldvr, double *work, int *lwork, int *info);

typedef double complex cplx;

/* Solve for an eigenvector of A (row-major, n x n) belonging to lam via
 * inverse iteration.  Returns 0 on success, -1 if no accurate vector found. */
static int eigvec_inverse_iteration(int n, const double *A, cplx lam, cplx *v,
                                    double anorm)
{
    cplx M[MAXN * MAXN];
    int piv[MAXN];
    int i, j, k, it;
    double tiny = 1e-300;
    double pivfloor = 2.3e-16 * (anorm > 0.0 ? anorm : 1.0);
    if (pivfloor <= 0.0)
        pivfloor = 2.3e-16;

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++)
            M[i * n + j] = A[i * n + j];
        M[i * n + i] -= lam;
    }

    /* LU with partial pivoting, singular pivots perturbed. */
    for (k = 0; k < n; k++) {
        int p = k;
        double best = cabs(M[k * n + k]);
        for (i = k + 1; i < n; i++) {
            double m = cabs(M[i * n + k]);
            if (m > best) { best = m; p = i; }
        }
        piv[k] = p;
        if (p != k) {
            for (j = 0; j < n; j++) {
                cplx t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
        }
        if (cabs(M[k * n + k]) < pivfloor)
            M[k * n + k] = pivfloor;
        for (i = k + 1; i < n; i++) {
            cplx f = M[i * n + k] / M[k * n + k];
            M[i * n + k] = f;
            if (f != 0.0)
                for (j = k + 1; j < n; j++)
                    M[i * n + j] -= f * M[k * n + j];
        }
    }

    for (i = 0; i < n; i++)
        v[i] = 1.0 / (double)(i + 1) + 0.25 * (double)((i * 7) % 5);

    for (it = 0; it < 6; it++) {
        cplx y[MAXN];
        double nrm, res, scale;
        /* apply row swaps */
        for (i = 0; i < n; i++)
            y[i] = v[i];
        for (k = 0; k < n; k++) {
            int p = piv[k];
            if (p != k) { cplx t = y[k]; y[k] = y[p]; y[p] = t; }
        }
        /* forward solve L y = Pb */
        for (i = 1; i < n; i++)
            for (j = 0; j < i; j++)
                y[i] -= M[i * n + j] * y[j];
        /* back solve U x = y */
        for (i = n - 1; i >= 0; i--) {
            for (j = i + 1; j < n; j++)
                y[i] -= M[i * n + j] * y[j];
            y[i] /= M[i * n + i];
        }
        nrm = 0.0;
        for (i = 0; i < n; i++) {
            double a = creal(y[i]), b = cimag(y[i]);
            nrm += a * a + b * b;
        }
        nrm = sqrt(nrm);
        if (!(nrm > tiny) || !isfinite(nrm))
            return -1;
        scale = 1.0 / nrm;
        for (i = 0; i < n; i++)
            v[i] = y[i] * scale;

        /* residual || A v - lam v || (v has unit norm) */
        res = 0.0;
        for (i = 0; i < n; i++) {
            cplx s = 0.0;
            for (j = 0; j < n; j++)
                s += A[i * n + j] * v[j];
            s -= lam * v[i];
            res += creal(s) * creal(s) + cimag(s) * cimag(s);
        }
        res = sqrt(res);
        if (res <= 1e-11 * (anorm > 1.0 ? anorm : 1.0))
            return 0;
    }
    return -1;
}

static int dominant_eigenvalue(int n, const double *A, cplx *lam_out)
{
    if (n == 1) {
        *lam_out = A[0];
        return 0;
    }
    if (n == 2) {
        double tr = A[0] + A[3];
        double det = A[0] * A[3] - A[1] * A[2];
        double disc = tr * tr - 4.0 * det;
        if (disc >= 0.0) {
            double s = sqrt(disc);
            double l1 = 0.5 * (tr + s), l2 = 0.5 * (tr - s);
            *lam_out = (fabs(l1) >= fabs(l2)) ? l1 : l2;
        } else {
            double s = 0.5 * sqrt(-disc);
            *lam_out = 0.5 * tr + s * I;
        }
        return 0;
    }
    {
        double a[MAXN * MAXN];
        double wr[MAXN], wi[MAXN];
        double work[8 * MAXN + 64];
        char jobvl = 'N', jobvr = 'N';
        int nn = n, lda = n, ldv = 1, lwork = 8 * MAXN + 64, info = 0;
        double dummy = 0.0;
        int i, best = 0;
        double bestmag = -1.0;
        /* LAPACK is column major: transpose (eigenvalues are unchanged). */
        for (i = 0; i < n; i++) {
            int j;
            for (j = 0; j < n; j++)
                a[j * n + i] = A[i * n + j];
        }
        dgeev_(&jobvl, &jobvr, &nn, a, &lda, wr, wi, &dummy, &ldv, &dummy, &ldv,
               work, &lwork, &info);
        if (info != 0)
            return -1;
        for (i = 0; i < n; i++) {
            double m = hypot(wr[i], wi[i]);
            if (m > bestmag) { bestmag = m; best = i; }
        }
        if (!isfinite(bestmag))
            return -1;
        *lam_out = wr[best] + wi[best] * I;
        return 0;
    }
}

static PyObject *dominant(PyObject *self, PyObject *arg)
{
    Py_buffer view;
    double A[MAXN * MAXN];
    cplx v[MAXN];
    cplx lam;
    double anorm = 0.0;
    int n, i, j, iscomplex;
    PyObject *res, *val, *ba;

    if (PyObject_GetBuffer(arg, &view, PyBUF_STRIDES | PyBUF_FORMAT) != 0) {
        PyErr_Clear();
        Py_RETURN_NONE;
    }
    if (view.ndim != 2 || view.shape[0] != view.shape[1] ||
        view.shape[0] < 1 || view.shape[0] > MAXN || view.itemsize != 8 ||
        view.format == NULL || (view.format[0] != 'd' && view.format[0] != '<')) {
        PyBuffer_Release(&view);
        Py_RETURN_NONE;
    }
    n = (int)view.shape[0];
    {
        const char *base = (const char *)view.buf;
        Py_ssize_t s0 = view.strides ? view.strides[0] : (Py_ssize_t)(8 * n);
        Py_ssize_t s1 = view.strides ? view.strides[1] : (Py_ssize_t)8;
        for (i = 0; i < n; i++) {
            const char *row = base + (Py_ssize_t)i * s0;
            for (j = 0; j < n; j++) {
                double x;
                memcpy(&x, row + (Py_ssize_t)j * s1, sizeof(double));
                if (!isfinite(x)) {
                    PyBuffer_Release(&view);
                    Py_RETURN_NONE;
                }
                A[i * n + j] = x;
                anorm += x * x;
            }
        }
    }
    PyBuffer_Release(&view);
    anorm = sqrt(anorm);

    if (dominant_eigenvalue(n, A, &lam) != 0)
        Py_RETURN_NONE;
    if (eigvec_inverse_iteration(n, A, lam, v, anorm) != 0)
        Py_RETURN_NONE;

    iscomplex = (cimag(lam) != 0.0);
    if (!iscomplex) {
        for (i = 0; i < n; i++)
            if (cimag(v[i]) != 0.0) { iscomplex = 1; break; }
    }

    if (iscomplex) {
        ba = PyByteArray_FromStringAndSize(NULL, (Py_ssize_t)n * 16);
        if (ba == NULL)
            return NULL;
        memcpy(PyByteArray_AS_STRING(ba), v, (size_t)n * 16);
        val = PyComplex_FromDoubles(creal(lam), cimag(lam));
    } else {
        double rv[MAXN];
        for (i = 0; i < n; i++)
            rv[i] = creal(v[i]);
        ba = PyByteArray_FromStringAndSize(NULL, (Py_ssize_t)n * 8);
        if (ba == NULL)
            return NULL;
        memcpy(PyByteArray_AS_STRING(ba), rv, (size_t)n * 8);
        val = PyFloat_FromDouble(creal(lam));
    }
    if (val == NULL) { Py_DECREF(ba); return NULL; }
    res = PyTuple_New(3);
    if (res == NULL) { Py_DECREF(ba); Py_DECREF(val); return NULL; }
    PyTuple_SET_ITEM(res, 0, val);
    PyTuple_SET_ITEM(res, 1, ba);
    PyTuple_SET_ITEM(res, 2, PyBool_FromLong(iscomplex));
    return res;
}

static PyMethodDef methods[] = {
    {"dominant", dominant, METH_O, "dominant eigenpair of a small real matrix"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_fasteig", NULL, -1, methods, NULL, NULL, NULL, NULL
};

PyMODINIT_FUNC PyInit__fasteig(void)
{
    return PyModule_Create(&moduledef);
}

