typedef double complex cplx;

#define SIGNC(a, b) ((b) >= 0.0 ? fabs(a) : -fabs(a))

/* Householder reduction of a (row-major, n x n) to upper Hessenberg form. */
static void hessenberg(int n, double *a)
{
    int k, i, j;
    for (k = 0; k < n - 2; k++) {
        double alpha = 0.0, beta, tau, u[MAXN];
        for (i = k + 1; i < n; i++)
            alpha += a[i * n + k] * a[i * n + k];
        alpha = sqrt(alpha);
        if (alpha == 0.0)
            continue;
        if (a[(k + 1) * n + k] > 0.0)
            alpha = -alpha;
        for (i = k + 1; i < n; i++)
            u[i] = a[i * n + k];
        u[k + 1] -= alpha;
        beta = 0.0;
        for (i = k + 1; i < n; i++)
            beta += u[i] * u[i];
        if (beta == 0.0)
            continue;
        tau = 2.0 / beta;
        /* A <- (I - tau u u^T) A  (rows k+1..n-1) */
        for (j = k; j < n; j++) {
            double s = 0.0;
            for (i = k + 1; i < n; i++)
                s += u[i] * a[i * n + j];
            s *= tau;
            for (i = k + 1; i < n; i++)
                a[i * n + j] -= s * u[i];
        }
        /* A <- A (I - tau u u^T)  (cols k+1..n-1) */
        for (i = 0; i < n; i++) {
            double s = 0.0;
            for (j = k + 1; j < n; j++)
                s += a[i * n + j] * u[j];
            s *= tau;
            for (j = k + 1; j < n; j++)
                a[i * n + j] -= s * u[j];
        }
        a[(k + 1) * n + k] = alpha;
        for (i = k + 2; i < n; i++)
            a[i * n + k] = 0.0;
    }
}

