                        r /= p;
                        for (j = k; j <= nn; j++) {
                            p = a[k * n + j] + q * a[(k + 1) * n + j];
                            if (k != nn - 1) {
                                p += r * a[(k + 2) * n + j];
                                a[(k + 2) * n + j] -= p * z;
                            }
                            a[(k + 1) * n + j] -= p * y;
                            a[k * n + j] -= p * x;
                        }
                        mmin = nn < k + 3 ? nn : k + 3;
                        for (i = l; i <= mmin; i++) {
                            p = x * a[i * n + k] + y * a[i * n + k + 1];
                            if (k != nn - 1) {
                                p += z * a[i * n + k + 2];
                                a[i * n + k + 2] -= p * r;
                            }
                            a[i * n + k + 1] -= p * q;
                            a[i * n + k] -= p;
                        }
                    }
                }
            }
        } while (l < nn - 1);
    }
    return 0;
}

